with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('komme til', 'phrase', 'dfb4aa8a-ba86-5532-bcb3-907d41c58978', 1, 'verb', null, 'to arrive (at a place)', 'Jeg kom til stationen for sent i morges.', 'I got to the station too late this morning.'), ('sige til', 'phrase', '24dc0ab0-4034-5387-86f4-39dd96a992fe', 1, 'verb', null, 'to let know (inform)', 'Jeg siger til, hvis jeg kommer for sent.', 'I''ll let you know if I''m late.'), ('lade være', 'phrase', '0d4d7509-0343-5f91-86e1-3b49896ac61f', 1, 'verb', null, 'to stop (doing something)', 'Han lovede at lade være med at ryge.', 'He promised not to smoke.'), ('tage til', 'phrase', '24aef06b-0b0c-52c8-9e17-d31a45e03fbc', 1, 'verb', null, 'to go to (a place)', 'Vi tager til stranden i morgen.', 'We are going to the beach tomorrow.'), ('tage til', 'phrase', '97b8b72f-33cd-5c1c-86da-752f4ee85041', 2, 'verb', null, 'to gain (weight, speed)', 'Bilen tager til i fart på motorvejen.', 'The car increases speed on the highway.'), ('gå med', 'phrase', 'a5f09b10-a08b-5a34-b8d1-534b557a44ff', 1, 'verb', null, 'to come along, join', 'Vil du gå med til festen på lørdag?', 'Would you like to come along to the party on Saturday?'), ('gå med', 'phrase', '7a91d63c-71af-58e5-9b0a-516e04ae8aa4', 2, 'verb', null, 'to wear (clothing, accessories)', 'Hun gik med en rød kjole i går.', 'She wore a red dress yesterday.'), ('gå på', 'phrase', 'bc3d15dd-b6cb-55ee-a4ba-8608712aa11b', 1, 'verb', null, 'to attend (school, a course)', 'Hun gik på universitetet i tre år.', 'She attended university for three years.'), ('gå ind', 'phrase', '7c4faba9-da97-572d-a6c9-7e09fa804690', 1, 'verb', null, 'to enter', 'Hun gik ind i huset uden at banke på.', 'She went into the house without knocking.'), ('give sig', 'phrase', '3b626196-43ed-5cdd-9f96-ed648e6b8723', 1, 'verb', null, 'to ease up (pain, weather)', 'Regnen gav sig endelig sidst på dagen.', 'The rain finally eased up at the end of the day.'), ('give sig', 'phrase', '34ed29d2-fc13-59b2-bdfe-57512e33beba', 2, 'verb', null, 'to give in, yield', 'Han gav sig til sidst og sagde ja.', 'He finally gave in and said yes.'), ('være nødt til', 'phrase', 'e3047c10-bf32-5c7e-8551-daa908847e4d', 1, 'verb', null, 'to have to (out of necessity)', 'Jeg er nødt til at gå nu.', 'I have to go now.'), ('tænke sig', 'phrase', 'e4743403-91fc-5535-9b7e-064e11d61277', 1, 'verb', null, 'to imagine', 'Tænk dig en verden uden biler.', 'Imagine a world without cars.'), ('sidde på', 'phrase', '2def98ef-3b3d-5794-a61a-2b3b0a9ff441', 1, 'verb', null, 'to sit on (something)', 'Katten sidder på stolen hele dagen.', 'The cat sits on the chair all day.'), ('sidde på', 'phrase', '82120d26-ba58-5c66-8022-a933ef320713', 2, 'verb', null, 'to keep (information, a secret) to oneself', 'Hun sad på hemmeligheden i mange år.', 'She kept the secret for many years.'), ('tænke sig at', 'phrase', '75ea44ac-4248-5807-8442-e8586ea47108', 1, 'verb', null, 'to imagine (that)', 'Tænk dig at bo i sådan et hus.', 'Imagine living in such a house.'), ('spille på', 'phrase', '2138f8fb-1739-557f-a1cd-d66fccfbb900', 1, 'verb', null, 'to play (a musical instrument)', 'Han spiller på guitar hver aften.', 'He plays the guitar every evening.'), ('skrive til', 'phrase', 'd92c6556-bf4d-5bbb-a471-f91871b1cb3c', 1, 'verb', null, 'to write (to someone)', 'Jeg skriver til min ven hver uge.', 'I write to my friend every week.'), ('stå på', 'phrase', 'd71e450f-8bd8-5d44-9f61-e8f1069b50b1', 1, 'verb', null, 'to go on', 'Mødet står på i to timer.', 'The meeting lasts for two hours.'), ('have lyst', 'phrase', '090dfece-973c-5b61-9024-61ab437756f9', 1, 'verb', null, 'to want (to feel like)', 'Jeg har lyst til en kop te.', 'I feel like a cup of tea.'), ('gå ned', 'phrase', '6f7cc22d-c22f-54a3-be77-2aeaf58fbc2d', 1, 'verb', null, 'to go down', 'Vi gik ned ad trappen til stuen.', 'We walked down the stairs to the living room.'), ('gå ned', 'phrase', 'fed3e2ef-d7ec-5feb-b4fd-8ceb7644c6b8', 2, 'verb', null, 'to set (of the sun)', 'Solen går ned klokken otte om aftenen.', 'The sun sets at eight o''clock in the evening.'), ('gå ned', 'phrase', 'ad72cdba-2806-5866-805f-4ab1d80628c7', 3, 'verb', null, 'to go down (of price, weight)', 'Prisen på mælk er gået ned i denne uge.', 'The price of milk has gone down this week.'), ('slå sig', 'phrase', '0320fc18-c821-52d6-a8bb-67680210a0a5', 1, 'verb', null, 'to hurt oneself', 'Jeg slog mig på knæet, da jeg faldt.', 'I hurt my knee when I fell.'), ('rejse til', 'phrase', '562dd029-48c3-5d1e-b998-36881b2a0de1', 1, 'verb', null, 'to travel to (a place)', 'Vi rejser til Spanien hver sommer.', 'We travel to Spain every summer.'), ('være til', 'phrase', '097ffea8-5b2c-5157-ae75-4c85e3f3e09f', 1, 'verb', null, 'to exist', 'Mange tror, at spøgelser er til.', 'Many people believe that ghosts exist.'), ('blive til', 'phrase', 'fb8e0fea-8f18-5979-b681-929fd04e10e5', 1, 'verb', null, 'to become (turn into)', 'Vandet blev til is i løbet af natten.', 'The water turned to ice during the night.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0001' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
